export function makeDialogueTrigger(event, target, speaker, text, style, playCry, screenShake, repeat, turn, speakerName, showNamebox, textboxType, choices, choiceResponses, choiceEffects){
  var tbType = ["default", "cinematic", "speech", "clean"].includes(String(textboxType || "").toLowerCase()) ? String(textboxType).toLowerCase() : (style === "narrative" ? "default" : "cinematic");
  return {
    id: uid("dia"),
    event: String(event || "RoundStartCommand"),
    target: ["boss", "sos", "player", "global"].includes(String(target || "").toLowerCase()) ? String(target).toLowerCase() : "boss",
    speaker: ["boss", "sos", "trainer", "narrator", "custom"].includes(String(speaker || "").toLowerCase()) ? String(speaker).toLowerCase() : "boss",
    speakerName: String(speakerName || ""),
    text: String(text || ""),
    style: String(style || "").toLowerCase() === "narrative" ? "narrative" : "cinematic",
    textboxType: tbType,
    showNamebox: showNamebox !== false,
    choices: Array.isArray(choices) ? choices.map(String) : (typeof choices === "string" ? choices.split(/[,\n]/).map(s=>s.trim()).filter(Boolean) : []),
    choiceResponses: Array.isArray(choiceResponses) ? choiceResponses.map(String) : (typeof choiceResponses === "string" ? choiceResponses.split("\n").map(s=>s.trim()) : []),
    choiceEffects: Array.isArray(choiceEffects) ? choiceEffects : [],
    playCry: playCry === true,
    screenShake: screenShake === true,
    repeat: repeat === true,
    turn: Math.max(0, parseInt(turn, 10) || 0)
  };
}
export function normalizeDialogueTrigger(raw){
  if(!raw || typeof raw !== "object") return null;
  var target = String(raw.target || "").toLowerCase();
  if(!["boss", "sos", "player", "global"].includes(target)){
    var rawEv = String(raw.event || "");
    if(rawEv.includes("_player")) target = "player";
    else if(rawEv.includes("_sos")) target = "sos";
    else target = "boss";
  }
  var speaker = String(raw.speaker || "").toLowerCase();
  if(speaker === "opponent") speaker = target === "sos" ? "sos" : "boss";
  if(!["boss", "sos", "trainer", "narrator", "custom"].includes(speaker)) speaker = "boss";
  var ev = String(raw.event || "RoundStartCommand").trim();
  var cleanEv = ev.replace(/_(foe\d*|player\d*|sos\d*|ally\d*)$/i, "");
  if(!cleanEv) cleanEv = ev;
  var style = String(raw.style || "").toLowerCase() === "narrative" ? "narrative" : "cinematic";
  var tbType = String(raw.textboxType || "").toLowerCase();
  if(!["default", "cinematic", "speech", "clean"].includes(tbType)){
    tbType = style === "narrative" ? "default" : "cinematic";
  }
  var rawChoices = raw.choices;
  var choices = Array.isArray(rawChoices) ? rawChoices.map(String) : (typeof rawChoices === "string" ? rawChoices.split(/[,\n]/).map(s=>s.trim()).filter(Boolean) : []);
  var rawResp = raw.choiceResponses;
  var choiceResponses = Array.isArray(rawResp) ? rawResp.map(String) : (typeof rawResp === "string" ? rawResp.split("\n").map(s=>s.trim()) : []);
  var rawEffects = raw.choiceEffects;
  var choiceEffects = Array.isArray(rawEffects) ? rawEffects.map(function(eff){
    if(!eff || typeof eff !== "object") return null;
    return {
      type: String(eff.type || "none").toLowerCase(),
      stat: String(eff.stat || "ATTACK").toUpperCase(),
      stages: Math.max(1, Math.min(6, parseInt(eff.stages, 10) || 1)),
      target: ["player", "boss", "both"].includes(String(eff.target || "").toLowerCase()) ? String(eff.target).toLowerCase() : "player",
      percent: Math.max(1, Math.min(100, parseInt(eff.percent, 10) || 25)),
      status: String(eff.status || "").toUpperCase()
    };
  }).filter(Boolean) : [];

  return {
    id: String(raw.id || uid("dia")),
    event: cleanEv,
    rawEvent: ev,
    target: target,
    speaker: speaker,
    speakerName: String(raw.speakerName || ""),
    text: String(raw.text || ""),
    style: style,
    textboxType: tbType,
    showNamebox: raw.showNamebox !== false,
    choices: choices,
    choiceResponses: choiceResponses,
    choiceEffects: choiceEffects,
    playCry: raw.playCry === true,
    screenShake: raw.screenShake === true,
    repeat: raw.repeat === true,
    turn: Math.max(0, parseInt(raw.turn, 10) || 0)
  };
}
